solution.solution.cpp:
#include <stdexcept>

double safeDivide(double a, double b)
{
    if (b == 0.0)
    {
        throw std::invalid_argument{ "division by zero" };
    }
    return a / b;
}

unitTests:
TEST("divides") { CHECK_NEAR(safeDivide(10, 4), 2.5, 1e-12); CHECK_NEAR(safeDivide(0, 5), 0.0, 1e-12); }
TEST("throws on zero") { CHECK_THROWS_AS(safeDivide(1, 0), std::invalid_argument); }
TEST("the message says what went wrong") { try { safeDivide(1, 0); CHECK(false); } catch (const std::exception& e) { CHECK_EQ(std::string{ e.what() }, "division by zero"); } }

